def norm_conn(a):
    c = a.get("connection", "main")
    if c == "other":
        return "other"
    return "main"


def simulate(cand, actions):
    committed = {}
    txns = {}
    open_conn = None
    total = {"main": 0, "other": 0}
    main_last = 0
    for a in actions:
        op = a.get("op")
        if op == "begin" or op == "commit" or op == "rollback":
            c = norm_conn(a)
            if op == "begin":
                if open_conn is None:
                    open_conn = c
                    txns[c] = {"pending": {}, "implicit": False, "stack": []}
            else:
                if open_conn == c:
                    t = txns[c]
                    if op == "commit":
                        for k in t["pending"]:
                            v = t["pending"][k]
                            if v is None:
                                committed.pop(k, None)
                            else:
                                committed[k] = v
                    txns.pop(c, None)
                    open_conn = None
        elif op == "savepoint" or op == "rollback_to" or op == "release":
            c = norm_conn(a)
            if open_conn is not None:
                c = open_conn
            name = a.get("name")
            if op == "savepoint":
                if open_conn is None:
                    open_conn = c
                    txns[c] = {"pending": {}, "implicit": True, "stack": []}
                t = txns[c]
                t["stack"].append([name, dict(t["pending"])])
            else:
                if open_conn == c:
                    t = txns[c]
                    stack = t["stack"]
                    idx = -1
                    for i in range(len(stack) - 1, -1, -1):
                        if stack[i][0] == name:
                            idx = i
                            break
                    if idx >= 0:
                        if op == "rollback_to":
                            t["pending"] = dict(stack[idx][1])
                            del stack[idx + 1:]
                        else:
                            del stack[idx:]
                            if len(stack) == 0 and t["implicit"]:
                                for k in t["pending"]:
                                    v = t["pending"][k]
                                    if v is None:
                                        committed.pop(k, None)
                                    else:
                                        committed[k] = v
                                txns.pop(c, None)
                                open_conn = None
        else:
            if open_conn is not None:
                c = open_conn
            else:
                c = norm_conn(a)
            key = a.get("key")
            t = None
            if open_conn is not None:
                t = txns.get(c)
            pending = None
            exists = False
            if t is not None:
                pending = t["pending"]
                exists = key in pending or key in committed
            else:
                exists = key in committed
            ch = 0
            fired = False
            if op == "put":
                v = a.get("value")
                if exists:
                    if cand["conflict"] == "ignore":
                        ch = 0
                    else:
                        if cand["conflict"] == "upsert":
                            ch = 1
                        else:
                            ch = 2
                        fired = True
                        if pending is not None:
                            pending[key] = v
                        else:
                            committed[key] = v
                else:
                    ch = 1
                    fired = True
                    if pending is not None:
                        pending[key] = v
                    else:
                        committed[key] = v
            elif op == "update":
                if exists:
                    ch = 1
                    if pending is not None:
                        pending[key] = a.get("value")
                    else:
                        committed[key] = a.get("value")
            elif op == "delete":
                if exists:
                    ch = 1
                    if pending is not None:
                        pending[key] = None
                    else:
                        committed.pop(key, None)
            extra = 0
            if fired and cand["trigger"]:
                extra = 1
            total[c] = total[c] + ch + extra
            if c == "main":
                main_last = ch + extra
    if cand["channel"] == "changes":
        chan = main_last
    elif cand["channel"] == "total_main":
        chan = total["main"]
    else:
        chan = total["main"] + total["other"]
    s = 0
    for v in committed.values():
        s = s + v
    return {"channel": chan, "count": len(committed), "sum": s}


def investigate(context, acquire):
    hist = acquire("history")
    survivors = []
    for conflict in ["ignore", "replace", "upsert"]:
        for channel in ["changes", "total_main", "both"]:
            for trig in [False, True]:
                cand = {"conflict": conflict, "channel": channel, "trigger": trig}
                ok = True
                for r in hist:
                    obs = r.get("observed")
                    res = simulate(cand, r.get("actions", []))
                    if res["channel"] != obs.get("channel"):
                        ok = False
                    if res["count"] != obs.get("committed_count"):
                        ok = False
                    if res["sum"] != obs.get("committed_sum"):
                        ok = False
                    if not ok:
                        break
                if ok:
                    survivors.append(cand)
    if len(survivors) == 0:
        return {"value": None, "unresolved": True}
    goal = context.get("goal")
    vals = []
    for cand in survivors:
        res = simulate(cand, context.get("actions", []))
        if goal == "channel":
            vals.append(res["channel"])
        elif goal == "committed_count":
            vals.append(res["count"])
        else:
            vals.append(res["sum"])
    first = vals[0]
    for v in vals:
        if v != first:
            return {"value": None, "unresolved": True}
    return {"value": first, "unresolved": False}
